package cn.balltv.portal;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;
public class FeedsTest {
    JSONObject wrap(String s)throws Exception{return new JSONObject("{data:"+s+"}");}
    @Test public void coffeeGroupsCommentatorsWithoutMixingSources()throws Exception{Feeds.Page p=Feeds.parse("咖啡","live",wrap("[{match_id:12,room_id:'1',home_team:'甲',away_team:'乙',stream_url:'https://example.com/a.m3u8'},{match_id:12,room_id:'2'}]"));assertEquals(1,p.items.size());assertEquals("1",p.items.get(0).room);assertFalse(p.more);assertEquals("甲  vs  乙",p.items.get(0).label());}
    @Test public void coffeeScheduleUsesRoomIdentifierNotArchorId()throws Exception{Feeds.Match m=Feeds.parse("咖啡","schedule",wrap("[{match_id:22,archors:[{id:9,room_id:'1009'}],status:'upcoming'}]")).items.get(0);assertEquals("1009",m.room);}
    @Test public void unavailableScheduleHasNoInventedRoom()throws Exception{assertEquals("",Feeds.parse("咖啡","schedule",wrap("[{match_id:22,archors:[]}]")).items.get(0).room);}
    @Test public void doubaoScheduleUsesNestedMatchAndCursor()throws Exception{Feeds.Page p=Feeds.parse("豆包","schedule",wrap("{items:[{match:{id:7,home:'甲',away:'乙',status:3,playUrl:'/play/7-1-2'},rooms:[]}],hasMore:true,nextCursor:'abc&def'}"));assertEquals("deferred",p.items.get(0).status);assertEquals("7-1-2",p.items.get(0).room);assertTrue(p.more);assertTrue(Feeds.path("豆包","schedule",2,p.cursor).contains("abc%26def"));}
    @Test public void doubaoGroupsDuplicateRooms()throws Exception{Feeds.Page p=Feeds.parse("豆包","live",wrap("{items:[{matchId:7,id:1,url:'/play/7-1-1',status:1},{matchId:7,id:2,url:'/play/7-1-2',status:1}],total:2,page:1,pageSize:30}"));assertEquals(1,p.items.size());assertEquals("7",p.items.get(0).id);assertEquals("7-1-1",p.items.get(0).room);assertFalse(p.more);}
    @Test public void coffeeReplayReadsVideoUrl()throws Exception{Feeds.Match m=new Feeds.Match();m.source="咖啡";m.kind="replay";java.util.ArrayList<Feeds.Line> lines=Feeds.parseLines(m,new JSONObject("{replays:[{title:'全场',video_url:'https://example.com/replay.m3u8'}]}"));assertEquals("https://example.com/replay.m3u8",lines.get(0).url);}
    @Test public void doubaoReplayResolvesRelativeProxy()throws Exception{Feeds.Match m=new Feeds.Match();m.source="豆包";m.kind="replay";assertEquals(Feeds.DOUBAO+"/vodplay/7-1.m3u8",Feeds.parseLines(m,new JSONObject("{lines:[{title:'全场',routeId:'7-1',proxyUrl:'/vodplay/7-1.m3u8'}]}")).get(0).url);}
    @Test public void doubaoLiveStoresResolveIdNotStaleUrl()throws Exception{Feeds.Match m=new Feeds.Match();m.source="豆包";m.kind="live";Feeds.Line line=Feeds.parseLines(m,new JSONObject("{signals:[{name:'原声',playId:'7-1-2',url:'/play/7-1-2'}]}")).get(0);assertEquals("7-1-2",line.id);assertEquals("",line.url);}
    @Test public void emptyResponsesRemainEmpty()throws Exception{assertTrue(Feeds.parse("咖啡","live",wrap("[]")).items.isEmpty());assertTrue(Feeds.parse("豆包","live",wrap("{items:[]}")).items.isEmpty());}
    @Test public void sourceIdentifiersNeverCollide()throws Exception{Feeds.Match a=Feeds.parse("咖啡","live",wrap("[{match_id:7,room_id:'1'}]")).items.get(0),b=Feeds.parse("豆包","live",wrap("{items:[{matchId:7,id:1}]}" )).items.get(0);assertNotEquals(a.key(),b.key());}
}
